  "amount" decimal(14,2),
  "expense_account_id" bigint
);

CREATE TABLE "vendor_payment" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "branch_id" bigint NOT NULL,
  "payment_no" varchar(30) UNIQUE NOT NULL,
  "vendor_id" bigint NOT NULL,
  "payment_date" date NOT NULL,
  "amount" decimal(14,2) NOT NULL,
  "currency_id" bigint,
  "payment_method_id" bigint,
  "reference_no" varchar(100),
  "paid_by" bigint,
  "status_id" bigint,
  "journal_entry_id" bigint,
  "notes" text
);

CREATE TABLE "vendor_payment_allocation" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vendor_payment_id" bigint NOT NULL,
  "vendor_bill_id" bigint NOT NULL,
  "amount" decimal(14,2) NOT NULL
);

CREATE TABLE "currency" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" char(3) UNIQUE NOT NULL,
  "name_en" varchar(50),
  "name_ar" varchar(50),
  "symbol" varchar(10),
  "decimal_places" smallint DEFAULT 2,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "fiscal_period" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" bigint NOT NULL,
  "year" smallint NOT NULL,
  "period_no" smallint NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "is_closed" boolean DEFAULT false
);

CREATE TABLE "account" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" bigint NOT NULL,
  "parent_account_id" bigint,
  "account_type_id" bigint,
  "account_code" varchar(20) NOT NULL,
  "name_en" varchar(200),
  "name_ar" varchar(200),
  "level" smallint,
  "is_group" boolean DEFAULT false,
  "is_postable" boolean DEFAULT true,
  "currency_id" bigint,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "account_mapping" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" bigint NOT NULL,
  "branch_id" bigint,
  "source_type" varchar(50) NOT NULL,
  "source_key_id" bigint,
  "debit_account_id" bigint,
  "credit_account_id" bigint,
  "is_active" boolean DEFAULT true
);

CREATE TABLE "journal_entry" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" bigint NOT NULL,
  "branch_id" bigint NOT NULL,
  "journal_no" varchar(30) UNIQUE NOT NULL,
  "entry_date" date NOT NULL,
  "fiscal_period_id" bigint NOT NULL,
  "currency_id" bigint,
  "exchange_rate" decimal(18,6) DEFAULT 1,
  "description" text,
  "source_type" varchar(50),
  "source_id" bigint,
  "status_id" bigint,
  "posted_at" timestamptz,
  "posted_by" bigint,
  "reversed_entry_id" bigint
);

CREATE TABLE "journal_line" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "journal_entry_id" bigint NOT NULL,
  "account_id" bigint NOT NULL,
  "description" varchar(300),
  "debit" decimal(14,2) DEFAULT 0,
  "credit" decimal(14,2) DEFAULT 0,
  "base_debit" decimal(14,2) DEFAULT 0,
  "base_credit" decimal(14,2) DEFAULT 0,
  "building_id" bigint,
  "unit_id" bigint,
  "tenant_id" bigint,
  "vendor_id" bigint,
  "contract_id" bigint
);

CREATE TABLE "document" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "branch_id" bigint,
  "entity_type" varchar(50) NOT NULL,
  "entity_id" bigint NOT NULL,
  "document_type_id" bigint,
  "file_name" varchar(255),
  "file_path" varchar(500),
  "mime_type" varchar(100),
  "size_bytes" bigint,
  "expiry_date" date
);

CREATE TABLE "activity_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "branch_id" bigint,
  "building_id" bigint,
  "entity_type" varchar(50),
  "entity_id" bigint,
  "action" varchar(50),
  "severity_id" bigint,
  "description" text,
  "old_values" jsonb,
  "new_values" jsonb,
  "user_id" bigint,
  "occurred_at" timestamptz NOT NULL
);

CREATE TABLE "number_sequence" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "company_id" bigint NOT NULL,
  "branch_id" bigint,
  "prefix" varchar(10) NOT NULL,
  "year" smallint,
  "last_value" int DEFAULT 0,
  "padding" smallint DEFAULT 4
);

